// 从路由表生成 OpenAPI 3.1 文档（文档即代码：路由是唯一事实来源）
const routes = [
  { method: 'get', path: '/articles', operationId: 'listArticles', tag: 'Articles',
    query: [
      { name: 'limit', schema: { type: 'integer', minimum: 1, maximum: 100 } },
      { name: 'cursor', schema: { type: 'string' } },
      { name: 'sort', schema: { type: 'string', enum: ['createdAt', '-createdAt', 'score', '-score'] } },
    ],
    responses: { 200: 'ArticleList' } },
  { method: 'post', path: '/articles', operationId: 'createArticle', tag: 'Articles',
    body: 'ArticleCreate',
    responses: { 201: 'Article', 400: 'Problem', 409: 'Problem', 422: 'Problem' } },
  { method: 'get', path: '/articles/{id}', operationId: 'getArticle', tag: 'Articles',
    params: [{ name: 'id', schema: { type: 'string', pattern: '^[0-9]+$' } }],
    responses: { 200: 'Article', 404: 'Problem' } },
  { method: 'delete', path: '/articles/{id}', operationId: 'deleteArticle', tag: 'Articles',
    params: [{ name: 'id', schema: { type: 'string', pattern: '^[0-9]+$' } }],
    responses: { 204: null, 404: 'Problem' } },
];

const STATUS_TEXT = {
  200: 'OK', 201: 'Created', 204: 'No Content', 400: 'Bad Request',
  404: 'Not Found', 409: 'Conflict', 422: 'Unprocessable Content',
};

function responseObject(code, schemaName) {
  const entry = { description: STATUS_TEXT[code] || 'Response' };
  if (schemaName === null) return entry;                       // 204 无响应体
  const media = schemaName === 'Problem' ? 'application/problem+json' : 'application/json';
  entry.content = {};
  entry.content[media] = { schema: { $ref: '#/components/schemas/' + schemaName } };
  return entry;
}

function buildOpenApi(routes, info) {
  const doc = { openapi: '3.1.0', info: info, paths: {}, components: { schemas: {} } };
  for (const r of routes) {
    if (!doc.paths[r.path]) doc.paths[r.path] = {};
    const op = { operationId: r.operationId, tags: [r.tag], parameters: [], responses: {} };
    for (const p of r.params || []) {
      op.parameters.push({ name: p.name, in: 'path', required: true, schema: p.schema });
    }
    for (const q of r.query || []) {
      op.parameters.push({ name: q.name, in: 'query', required: false, schema: q.schema });
    }
    if (r.body) {
      op.requestBody = {
        required: true,
        content: { 'application/json': { schema: { $ref: '#/components/schemas/' + r.body } } },
      };
    }
    for (const code of Object.keys(r.responses)) {
      op.responses[code] = responseObject(Number(code), r.responses[code]);
    }
    doc.paths[r.path][r.method] = op;
  }
  doc.components.schemas.Problem = {
    type: 'object',
    required: ['type', 'title', 'status'],
    properties: {
      type: { type: 'string', format: 'uri-reference' },
      title: { type: 'string' },
      status: { type: 'integer' },
      detail: { type: 'string' },
      instance: { type: 'string', format: 'uri-reference' },
    },
  };
  doc.components.schemas.Article = {
    type: 'object',
    required: ['id', 'title', 'status'],
    properties: {
      id: { type: 'string' },
      title: { type: 'string', maxLength: 40 },
      status: { type: 'string', enum: ['draft', 'published'] },
    },
  };
  doc.components.schemas.ArticleList = {
    type: 'object',
    properties: { data: { type: 'array', items: { $ref: '#/components/schemas/Article' } },
                  total: { type: 'integer' } },
  };
  doc.components.schemas.ArticleCreate = {
    type: 'object',
    required: ['title', 'status'],
    additionalProperties: false,
    properties: {
      title: { type: 'string', minLength: 1, maxLength: 40 },
      status: { type: 'string', enum: ['draft', 'published'] },
    },
  };
  return doc;
}

const doc = buildOpenApi(routes, { title: 'Articles API', version: '1.2.0' });
console.log(JSON.stringify(doc, null, 2));

const operations = [];
for (const p of Object.keys(doc.paths)) {
  for (const m of Object.keys(doc.paths[p])) {
    operations.push({ verb: m.toUpperCase(), path: p, operationId: doc.paths[p][m].operationId });
  }
}
console.log('--- self checks ---');
console.log('operations=' + operations.length);
for (const o of operations) console.log('  ' + o.verb + ' ' + o.path + ' -> ' + o.operationId);
console.log('unique_operation_ids=' + (new Set(operations.map(o => o.operationId)).size === operations.length));
console.log('path_params_always_required=' + Object.keys(doc.paths).every(p =>
  Object.keys(doc.paths[p]).every(m =>
    doc.paths[p][m].parameters.filter(x => x.in === 'path').every(x => x.required === true))));
console.log('every_operation_has_2xx=' + Object.keys(doc.paths).every(p =>
  Object.keys(doc.paths[p]).every(m =>
    Object.keys(doc.paths[p][m].responses).some(c => c[0] === '2'))));
console.log('every_4xx_uses_problem_json=' + Object.keys(doc.paths).every(p =>
  Object.keys(doc.paths[p]).every(m => Object.keys(doc.paths[p][m].responses)
    .filter(c => c[0] === '4')
    .every(c => doc.paths[p][m].responses[c].content['application/problem+json'] !== undefined))));
console.log('all_refs_resolve=' + JSON.stringify(doc).match(/#\/components\/schemas\/(\w+)/g)
  .every(function (ref) {
    const name = ref.split('/').pop();
    return Object.prototype.hasOwnProperty.call(doc.components.schemas, name);
  }));
